"use client";

import * as React from "react";
import { cva, type VariantProps } from "class-variance-authority";
import { cn } from "../../lib/utils";
import { ChevronLeft, ChevronRight } from "./icons";

// Pagination: generated by UIX from the design system. Same variants and sizes as the Figma component.

const paginationItemVariants = cva(
  "inline-flex shrink-0 cursor-pointer items-center justify-center transition-colors size-[36px] text-label-medium text-fg-secondary focus-visible:outline-none focus-visible:ring-3 focus-visible:ring-line-focus disabled:pointer-events-none disabled:text-fg-disabled rounded-md",
  {
    variants: {
      appearance: {
        outline: "border border-line-default hover:bg-subtle aria-[current=page]:border-line-brand aria-[current=page]:bg-brand-subtle aria-[current=page]:text-fg-brand",
        ghost: "hover:bg-subtle aria-[current=page]:bg-subtle aria-[current=page]:text-fg-brand",
        filled: "hover:bg-subtle aria-[current=page]:bg-brand aria-[current=page]:text-fg-on-brand aria-[current=page]:hover:bg-brand",
      },
    },
    defaultVariants: {
      appearance: "outline",
    },
  },
);

function pageRange(page: number, count: number, siblings: number) {
  const start = Math.max(2, page - siblings);
  const end = Math.min(count - 1, page + siblings);
  const out: (number | "gap")[] = [1];
  if (start > 2) out.push("gap");
  for (let p = start; p <= end; p++) out.push(p);
  if (end < count - 1) out.push("gap");
  if (count > 1) out.push(count);
  return out;
}

export interface PaginationProps
  extends Omit<React.HTMLAttributes<HTMLElement>, "onChange">,
    VariantProps<typeof paginationItemVariants> {
  /** Current page, starting at 1. */
  page: number;
  pageCount: number;
  onPageChange: (page: number) => void;
  /** Pages shown on each side of the current one. */
  siblings?: number;
}

const Pagination = React.forwardRef<HTMLElement, PaginationProps>(
  ({ className, appearance, page, pageCount, onPageChange, siblings = 1, ...props }, ref) => (
    <nav data-slot="pagination" data-kind="control" ref={ref} aria-label="Pagination" className={cn("skin-quiet flex items-center gap-1", className)} {...props}>
      <button type="button" aria-label="Previous page" disabled={page <= 1} onClick={() => onPageChange(page - 1)} className={cn(paginationItemVariants({ appearance }))}>
        <ChevronLeft aria-hidden className="size-4" />
      </button>
      {pageRange(page, pageCount, siblings).map((item, index) =>
        item === "gap" ? (
          <span key={"gap-" + index} aria-hidden className="inline-flex items-center justify-center size-[36px] text-fg-tertiary">
            …
          </span>
        ) : (
          <button key={item} type="button" aria-label={"Page " + item} aria-current={item === page ? "page" : void 0} onClick={() => onPageChange(item)} className={cn(paginationItemVariants({ appearance }))}>
            {item}
          </button>
        ),
      )}
      <button type="button" aria-label="Next page" disabled={page >= pageCount} onClick={() => onPageChange(page + 1)} className={cn(paginationItemVariants({ appearance }))}>
        <ChevronRight aria-hidden className="size-4" />
      </button>
    </nav>
  ),
);
Pagination.displayName = "Pagination";

export { Pagination, paginationItemVariants };
